<div class="panel table-wrap"><table><thead><tr><th>Time</th><th>Person</th><th>Action</th><th>Record</th><th>IP address</th></tr></thead><tbody><?php foreach ($items as $row): ?><tr><td><?= e($row['created_at']) ?></td><td><?= e($row['name'] ?? 'System') ?></td><td><?= e($row['action']) ?></td><td><?= e($row['entity']) ?> #<?= e($row['entity_id']) ?></td><td><?= e($row['ip_address']) ?></td></tr><?php endforeach ?><?php if (!$items): ?><tr><td colspan="5">No activity recorded yet.</td></tr><?php endif ?></tbody></table></div><?php require dirname(__DIR__).'/pagination.php'; ?>
